UPDATE v2.scenes SET note = '2025年周杰伦作曲、演奏并制作的官方单曲《即兴曲（Improvisation）》正式单曲封面；画面中的立式钢琴、服装、地毯、线缆与木地板对应伦敦艾比路录音室同次录制，仅作专辑封面参考，另见同地点官方MV原帧关联。' WHERE id = 'jay-20261009-r6-02';
UPDATE v2.scenes SET association_excerpt = '爱琴海的浪', note = '歌名及歌词（“爱琴海的浪”）均提及爱琴海，使用官方正式专辑封面参考；圣托里尼Ammoudi Bay仅作可到达海岸区域参考，不认定为MV拍摄点。' WHERE id = 'jay-20261008-13';
UPDATE v2.scenes SET association_excerpt = '西西里的夜色', note = '歌名及歌词（“西西里的夜色”）均提及西西里岛，使用官方正式专辑封面参考；巴勒莫公共广场仅作岛屿区域到达参考（MV实景科莫湖另列），不声称在西西里或教堂拍摄。' WHERE id = 'jay-20261008-16';
UPDATE v2.scenes SET association_excerpt = '你比大笨钟还笨', note = '歌名与歌词（“你比大笨钟还笨”）均以大笨钟比喻拌嘴，使用2012官方正式专辑封面作地点关联；伊丽莎白塔周边仅作公共道路到达参考，伦敦住宅门牌及MV屋顶机位未核。' WHERE id = 'jay-20261008-23';
DELETE FROM v2.scene_material_reviews WHERE scene_id IN ('jay-20261008-r5-02', 'jay-20261009-r8-02', 'jay-20261008-24');
